from datetime import datetime, timedelta, time
from pathlib import Path
import re

files = {'alice': Path('/app/alice_calendar.ics'), 'bob': Path('/app/bob_calendar.ics'), 'carol': Path('/app/carol_calendar.ics')}
cal = {}
for name, p in files.items():
    text = p.read_text()
    events = []
    for block in re.findall(r'BEGIN:VEVENT\n(.*?)\nEND:VEVENT', text, flags=re.S):
        s = re.search(r'DTSTART:(\d{8}T\d{6}Z)', block).group(1)
        e = re.search(r'DTEND:(\d{8}T\d{6}Z)', block).group(1)
        events.append((datetime.strptime(s, '%Y%m%dT%H%M%SZ'), datetime.strptime(e, '%Y%m%dT%H%M%SZ')))
    cal[name] = events

def overlaps(a_start, a_end, b_start, b_end):
    return a_start < b_end and b_start < a_end

def at(day, h, m=0):
    return datetime.combine(day.date(), time(h, m))

def valid(start):
    end = start + timedelta(hours=1)
    if start.weekday() >= 5:
        return False
    # Business hours, Alice, Bob, Carol same-day windows
    if not (at(start, 9) <= start and end <= at(start, 18)):
        return False
    if not (at(start, 9) <= start and end <= at(start, 14)):  # Alice hard constraint
        return False
    if start < at(start, 10):  # Bob hard constraint
        return False
    if start.weekday() in (1, 3) and end > at(start, 16, 30):
        return False
    if not (at(start, 9) <= start and end <= at(start, 17)):  # Carol hard constraint
        return False
    if overlaps(start, end, at(start, 12), at(start, 12, 30)):  # Carol lunch
        return False
    for evs in cal.values():
        for s, e in evs:
            if overlaps(start, end, s, e):
                return False
    return True

candidates = []
t = datetime(2024, 1, 15, 9)
end_scan = datetime(2024, 1, 19, 17)
while t <= end_scan:
    if valid(t):
        candidates.append(t)
    t += timedelta(minutes=1)

if not candidates:
    raise SystemExit('No valid candidates found')
non_monday = [c for c in candidates if c.weekday() != 0]
morning = [c for c in non_monday if time(9,0) <= c.time() and (c + timedelta(hours=1)).time() <= time(12,0)]
# Carol's Monday avoidance first; Alice morning preference next among otherwise valid slots.
chosen = morning[0] if morning else (non_monday[0] if non_monday else candidates[0])
print('Earliest chronological valid:', candidates[0].strftime('%Y-%m-%d %H:%M'), '-', (candidates[0] + timedelta(hours=1)).strftime('%H:%M'), candidates[0].strftime('%A'))
print('Earliest non-Monday valid:', non_monday[0].strftime('%Y-%m-%d %H:%M'), '-', (non_monday[0] + timedelta(hours=1)).strftime('%H:%M'), non_monday[0].strftime('%A'))
print('Earliest non-Monday morning valid:', morning[0].strftime('%Y-%m-%d %H:%M'), '-', (morning[0] + timedelta(hours=1)).strftime('%H:%M'), morning[0].strftime('%A'))
print('Chosen:', chosen.strftime('%Y%m%dT%H%M%SZ'), (chosen + timedelta(hours=1)).strftime('%Y%m%dT%H%M%SZ'))
print('First 20 candidates:')
for c in candidates[:20]:
    print(c.strftime('%Y-%m-%d %H:%M'), c.strftime('%A'))
